    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4, 5, 6, 7))
    namedValues = NamedValues(("allMac", 1), ("dynamicMac", 2), ("staticMac", 3), ("mcastMac", 4), ("pvlanCloneMac", 5), ("overlayMac", 6), ("secureMac", 7))

